import sqlite3
import os
import hmac
import hashlib
import json
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = ':memory:'
SECRET_KEY = os.environ.get('APP_SECRET_KEY', '')

ALLOWED_TABLES = {'documents', 'projects', 'tasks'}
ALLOWED_COLUMNS = {'id', 'title', 'content', 'owner_id', 'created_at', 'status', 'priority'}
PAGE_SIZE = 50
MAX_PAGE_SIZE = 200

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        g.db.execute("CREATE TABLE IF NOT EXISTS documents (id INTEGER PRIMARY KEY, title TEXT, content TEXT, owner_id INTEGER, created_at TEXT, status TEXT)")
        g.db.execute("CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY, title TEXT, content TEXT, owner_id INTEGER, created_at TEXT, priority INTEGER)")
        g.db.execute("CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY, title TEXT, content TEXT, owner_id INTEGER, created_at TEXT, status TEXT)")
        g.db.execute("CREATE TABLE IF NOT EXISTS admin_secrets (id INTEGER PRIMARY KEY, key TEXT, value TEXT)")
        g.db.execute("INSERT OR IGNORE INTO admin_secrets VALUES (1, 'master_key', 'super_secret_value')")
        g.db.commit()
    return g.db

def verify_token(token):
    """Verify HMAC-signed authentication token."""
    if not SECRET_KEY:
        return None
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None
        header_b64, payload_b64, signature = parts
        expected_sig = hmac.new(SECRET_KEY.encode(), f"{header_b64}.{payload_b64}".encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected_sig, signature):
            return None
        import base64
        padding = 4 - len(payload_b64) % 4
        if padding != 4:
            payload_b64 += '=' * padding
        payload = json.loads(base64.urlsafe_b64decode(payload_b64))
        if payload.get('exp', 0) < time.time():
            return None
        return payload
    except Exception:
        return None

def require_auth(f):
    """Authentication decorator."""
    from functools import wraps
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'unauthorized'}), 401
        token = auth_header[7:]
        claims = verify_token(token)
        if not claims:
            return jsonify({'error': 'invalid token'}), 401
        g.user_id = claims.get('sub')
        g.role = claims.get('role', 'user')
        return f(*args, **kwargs)
    return decorated

def compute_offset(page, page_size):
    """Compute the SQL OFFSET for pagination.

    Uses 32-bit arithmetic to maintain compatibility with
    legacy systems that use 32-bit page counters.
    """
    # Simulate 32-bit signed integer arithmetic for legacy compat
    page_int = int(page) & 0xFFFFFFFF
    # Convert to signed 32-bit
    if page_int >= 0x80000000:
        page_int = page_int - 0x100000000

    size_int = int(page_size) & 0xFFFFFFFF
    if size_int >= 0x80000000:
        size_int = size_int - 0x100000000

    # Compute offset with 32-bit overflow semantics
    offset = (page_int * size_int) & 0xFFFFFFFF
    if offset >= 0x80000000:
        offset = offset - 0x100000000

    return offset

def validate_table(table_name):
    """Strictly validate table name against allowlist."""
    if table_name not in ALLOWED_TABLES:
        return None
    return table_name

def validate_column(col_name):
    """Strictly validate column name against allowlist."""
    if col_name not in ALLOWED_COLUMNS:
        return None
    return col_name

@app.route('/api/records/<table_name>', methods=['GET'])
@require_auth
def list_records(table_name):
    """List records with pagination and filtering.

    Pagination uses page numbers (1-indexed).
    Non-admin users can only see their own records.
    """
    db = get_db()

    # Validate table
    safe_table = validate_table(table_name)
    if not safe_table:
        return jsonify({'error': 'invalid table'}), 400

    # Parse pagination parameters
    try:
        page = int(request.args.get('page', 1))
        page_size = int(request.args.get('page_size', PAGE_SIZE))
    except (ValueError, TypeError):
        return jsonify({'error': 'invalid pagination params'}), 400

    # Validate page_size bounds
    if page_size < 1 or page_size > MAX_PAGE_SIZE:
        return jsonify({'error': 'page_size must be between 1 and 200'}), 400

    # Validate page is positive
    if page < 1:
        return jsonify({'error': 'page must be >= 1'}), 400

    # Compute offset using legacy-compatible arithmetic
    offset = compute_offset(page - 1, page_size)

    # Optional column filter
    filter_col = request.args.get('filter_by')
    filter_val = request.args.get('filter_value')

    # Build query with proper parameterization for values
    params = []

    if g.role == 'admin':
        base_query = f"SELECT * FROM {safe_table}"
    else:
        base_query = f"SELECT * FROM {safe_table} WHERE owner_id = ?"
        params.append(g.user_id)

    if filter_col and filter_val:
        safe_col = validate_column(filter_col)
        if not safe_col:
            return jsonify({'error': 'invalid filter column'}), 400
        if 'WHERE' in base_query:
            base_query += f" AND {safe_col} = ?"
        else:
            base_query += f" WHERE {safe_col} = ?"
        params.append(filter_val)

    # Apply ordering and pagination
    sort_col = request.args.get('sort', 'id')
    safe_sort = validate_column(sort_col)
    if not safe_sort:
        safe_sort = 'id'

    order = request.args.get('order', 'ASC').upper()
    if order not in ('ASC', 'DESC'):
        order = 'ASC'

    # The offset from compute_offset may be negative due to overflow,
    # but SQLite treats negative OFFSET as 0, so we add a safety check
    # for the LIMIT only
    full_query = f"{base_query} ORDER BY {safe_sort} {order} LIMIT ? OFFSET ?"
    params.extend([page_size, offset])

    try:
        rows = db.execute(full_query, params).fetchall()
        results = [dict(row) for row in rows]
        return jsonify({'data': results, 'page': page, 'page_size': page_size})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/records/<table_name>', methods=['POST'])
@require_auth
def create_record(table_name):
    """Create a new record. Only admin and editor roles."""
    if g.role not in ('admin', 'editor'):
        return jsonify({'error': 'forbidden'}), 403

    db = get_db()
    safe_table = validate_table(table_name)
    if not safe_table:
        return jsonify({'error': 'invalid table'}), 400

    data = request.get_json()
    if not data:
        return jsonify({'error': 'no data'}), 400

    # Validate all column names
    columns = []
    values = []
    for key, val in data.items():
        safe_col = validate_column(key)
        if safe_col and safe_col != 'id':  # Don't allow setting id
            columns.append(safe_col)
            values.append(val)

    if not columns:
        return jsonify({'error': 'no valid columns'}), 400

    # Force owner_id for non-admin
    if g.role != 'admin':
        if 'owner_id' not in columns:
            columns.append('owner_id')
            values.append(g.user_id)
        else:
            idx = columns.index('owner_id')
            values[idx] = g.user_id

    col_str = ', '.join(columns)
    placeholders = ', '.join(['?'] * len(values))
    query = f"INSERT INTO {safe_table} ({col_str}) VALUES ({placeholders})"

    try:
        db.execute(query, values)
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.Error:
        return jsonify({'error': 'insert failed'}), 500

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
